        c0 = rem.pop(0)
        r.append(c0)
        load += demand(c0)
        while rem:
            last = r[-1]
            best_i = None
            best_s = None
            for i, c in enumerate(rem):
                dc = demand(c)
                if load + dc > cap:
                    continue
                s = dist(last, c)
                if best_s is None or s < best_s or (s == best_s and ksort(c) < ksort(rem[best_i])):
                    best_s = s
                    best_i = i
            if best_i is None:
                break
            c = rem.pop(best_i)
            r.append(c)
            load += demand(c)
        routes.append(r)

    def rlen(r):
        if not r:
            return 0.0
        s = dist(depot, r[0])
        for i in range(len(r) - 1):
            s += dist(r[i], r[i + 1])
        s += dist(r[-1], depot)
        return s

    def load(r):
        s = 0
        for c in r:
            s += demand(c)
        return s

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    miss = [c for c in cust if seen.get(c, 0) == 0]
    for c in miss:
        best = None
        best_pos = None
        best_delta = None
        dc = demand(c)
        for ri, r in enumerate(routes):
            if load(r) + dc > cap:
                continue
            for pos in range(len(r) + 1):
                p = depot if pos == 0 else r[pos - 1]
                n = depot if pos == len(r) else r[pos]
                delta = dist(p, c) + dist(c, n) - dist(p, n)
                if best_delta is None or delta < best_delta or (delta == best_delta and (ri, pos) < (best, best_pos)):
                    best = ri
                    best_pos = pos
                    best_delta = delta
        if best is None:
            routes.append([c])
        else:
            routes[best].insert(best_pos, c)

    changed = True
    while changed:
        changed = False
        for r in routes:
            n = len(r)
            if n < 4:
                continue
            base = rlen(r)
            bi = bj = None
            bg = 0.0
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    nr = r[:i + 1] + r[i + 1:j + 1][::-1] + r[j + 1:]
                    gain = base - rlen(nr)
                    if gain > bg + 1e-12:
                        bg = gain
                        bi, bj = i, j
            if bi is not None:
                r[:] = r[:bi + 1] + r[bi + 1:bj + 1][::-1] + r[bj + 1:]
                changed = True

    moved = True
    while moved:
        moved = False
        loads = [load(r) for r in routes]
        for a in range(len(routes)):
            ra = routes[a]
            if not ra:
                continue
            for idx, c in enumerate(list(ra)):
                dc = demand(c)
                prev_a = depot if idx == 0 else ra[idx - 1]
                next_a = depot if idx == len(ra) - 1 else ra[idx + 1]
                rem_cost = dist(prev_a, c) + dist(c, next_a) - dist(prev_a, next_a)
                best = None
                best_pos = None
                best_delta = 0.0
                for b in range(len(routes)):
                    if b == a or loads[b] + dc > cap:
                        continue
                    rb = routes[b]
                    ins_best = None
                    ins_pos = None
                    for pos in range(len(rb) + 1):
                        p = depot if pos == 0 else rb[pos - 1]
                        n = depot if pos == len(rb) else rb[pos]
                        ins = dist(p, c) + dist(c, n) - dist(p, n)
                        if ins_best is None or ins < ins_best or (ins == ins_best and pos < ins_pos):
                            ins_best = ins
                            ins_pos = pos
                    if ins_best is not None:
                        delta = ins_best - rem_cost
                        if delta < best_delta - 1e-12:
                            best_delta = delta
                            best = b
                            best_pos = ins_pos
                if best is not None:
                    ra.pop(idx)
                    routes[best].insert(best_pos, c)
                    moved = True
                    break
            if moved:
                break

    routes = [r for r in routes if r]

    used = set()
    for r in routes:
        i = 0
        while i < len(r):
            c = r[i]
            if c in used:
                r.pop(i)
            else:
                used.add(c)
                i += 1

    miss = [c for c in cust if c not in used]
    for c in miss:
        dc = demand(c)
        best = None
        best_pos = None
        best_delta = None
        for ri, r in enumerate(routes):
            if load(r) + dc > cap:
                continue
            for pos in range(len(r) + 1):
                p = depot if pos == 0 else r[pos - 1]
                n = depot if pos == len(r) else r[pos]
                delta = dist(p, c) + dist(c, n) - dist(p, n)
                if best_delta is None or delta < best_delta or (delta == best_delta and (ri, pos) < (best, best_pos)):
                    best = ri
                    best_pos = pos
                    best_delta = delta
        if best is None:
            routes.append([c])
        else:
            routes[best].insert(best_pos, c)

    for r in routes:
        if len(r) >= 2:
            seen_local = set()
            i = 0
            while i < len(r):
                if r[i] in seen_local:
                    r.pop(i)
                else:
                    seen_local.add(r[i])
                    i += 1

    routes = [r for r in routes if r]
    return routes
